package eu.kanade.tachiyomi.extension.all.hitomi

import eu.kanade.tachiyomi.network.GET
import okhttp3.Headers
import okhttp3.OkHttpClient

/**
 * Port of the image URL logic from https://ltn.gold-usergeneratedcontent.net/common.js and gg.js.
 *
 * Image path:  https://{w|a}{1 + gg.m(g)}.gold-usergeneratedcontent.net/{gg.b}{g}/{hash}.{webp|avif}
 * Thumbnail:   https://tn.gold-usergeneratedcontent.net/webpbigtn/{h[63]}/{h[61..62]}/{hash}.webp
 * where g = parseInt(hash[63] + hash[61..62], 16).
 *
 * gg.js is regenerated by the site regularly, so it is cached only for a few minutes.
 */
class HitomiImages(
    private val client: OkHttpClient,
    private val headers: Headers,
) {
    private class Gg(val cases: Set<Int>, val defaultO: Int, val caseO: Int, val b: String, val fetchedAt: Long) {
        fun m(g: Int) = if (g in cases) caseO else defaultO
    }

    @Volatile
    private var gg: Gg? = null

    private fun loadGg(): Gg {
        val cached = gg
        if (cached != null && System.currentTimeMillis() - cached.fetchedAt < GG_TTL_MS) return cached

        synchronized(this) {
            val again = gg
            if (again != null && System.currentTimeMillis() - again.fetchedAt < GG_TTL_MS) return again

            val js = client.newCall(GET("$LTN/gg.js?_=${System.currentTimeMillis()}", headers)).execute()
                .use { it.body.string() }

            val cases = CASE_REGEX.findAll(js).map { it.groupValues[1].toInt() }.toHashSet()
            val defaultO = DEFAULT_O_REGEX.find(js)?.groupValues?.get(1)?.toInt() ?: 0
            val caseO = CASE_O_REGEX.find(js)?.groupValues?.get(1)?.toInt() ?: 1
            val b = B_REGEX.find(js)?.groupValues?.get(1) ?: error("Unable to parse gg.js")

            return Gg(cases, defaultO, caseO, b, System.currentTimeMillis()).also { gg = it }
        }
    }

    /** Full-size image URL for [hash]. [format] is "webp" or "avif". */
    fun imageUrl(hash: String, format: String): String {
        val gg = loadGg()
        val g = imageId(hash)
        val prefix = if (format == "avif") "a" else "w"
        return "https://$prefix${1 + gg.m(g)}.$DOMAIN/${gg.b}$g/$hash.$format"
    }

    companion object {
        const val DOMAIN = "gold-usergeneratedcontent.net"
        const val LTN = "https://ltn.$DOMAIN"
        private const val GG_TTL_MS = 5 * 60 * 1000L

        private val CASE_REGEX = Regex("""case (\d+):""")
        private val DEFAULT_O_REGEX = Regex("""var o = (\d)""")
        private val CASE_O_REGEX = Regex("""o = (\d); break;""")
        private val B_REGEX = Regex("""b: '(\d+/)'""")

        fun imageId(hash: String): Int = (hash.takeLast(1) + hash.takeLast(3).take(2)).toInt(16)

        fun thumbnailUrl(hash: String): String {
            val last = hash.takeLast(1)
            val prev = hash.takeLast(3).take(2)
            return "https://tn.$DOMAIN/webpbigtn/$last/$prev/$hash.webp"
        }
    }
}
